class Perses < Formula
  desc 'Server and web UI for the CNCF sandbox for observability visualisation'
  homepage 'https://perses.dev'
  version '0.55.1'
  license 'Apache-2.0'

  if OS.linux?
    if Hardware::CPU.arm?
      url "https://github.com/perses/perses/releases/download/v#{version}/perses_#{version}_linux_arm64.tar.gz"
      sha256 'bd777b183622e2eaeda6645748be47d65afb67eb91aa8d8d726a7c10efd8a1c5'
    else
      url "https://github.com/perses/perses/releases/download/v#{version}/perses_#{version}_linux_amd64.tar.gz"
      sha256 '7c38ace5ce665e22d7d4f823b8bc0c8e91f9bcef381f218d8c564e0fe62ba750'
    end
  else
    if Hardware::CPU.arm?
      url "https://github.com/perses/perses/releases/download/v#{version}/perses_#{version}_darwin_arm64.tar.gz"
      sha256 'fa8424c68b0d1acce07869dec8967d102dd9d926f6a7e8ebaebd5ba292a97dcf'
    else
      url "https://github.com/perses/perses/releases/download/v#{version}/perses_#{version}_darwin_amd64.tar.gz"
      sha256 '0a6192711428d094f9e95ea5aafc06b166f7637e11ca42aa2cc4665b0ff01df8'
    end
  end

  def install
    bin.install 'perses'
    share.install 'plugins-archive'
    config = pkgetc/'config.yml'
    if config.exist?
      migrate_plugin_archive_path(config)
    else
      config.write <<~CFG
        plugin:
          archive_paths:
            - #{opt_share}/plugins-archive
        database:
          file:
            folder: #{var}/perses
      CFG
    end
    Dir.mkdir(var/'perses') unless Dir.exist?(var/'perses')
  end

  service do
    run [opt_bin/'perses', "--config", etc/"perses/config.yml"]
    keep_alive true
    log_path var/"log/perses.log"
    error_log_path var/"log/perses.log"
    working_dir var/"perses"
  end

  test do
    port = free_port
    pid = fork do
      exec bin/'perses', "-config", etc/"perses/config.yml", "-web.listen-address", "localhost:#{port}"
    end
    sleep 5
    assert_match "Perses", shell_output("curl -s localhost:#{port}")
  ensure
    Process.kill('TERM', pid)
    Process.wait(pid)
  end

  private

  # Perses v0.56.0 removed plugin.archive_path in favor of the list plugin.archive_paths, and refuses to start if the
  # configuration still uses it. Migrate the configuration generated by a previous version of this formula.
  def migrate_plugin_archive_path(config)
    content = config.read
    return if content.match?(/^[ \t]*archive_paths:/)

    migrated = content.sub(/^(?<indent>[ \t]*)archive_path:[ \t]*(?<path>\S.*)$/) do
      match = Regexp.last_match
      "#{match[:indent]}archive_paths:\n#{match[:indent]}  - #{match[:path]}"
    end
    config.atomic_write(migrated) if migrated != content
  end
end
